mapper.select:
SELECT 'EDHR_WORK_TASK' AS source_id, LPAD(CAST(mes_pro_edhr_work_task.id AS CHAR),20,'0') AS row_order_key, CAST(mes_pro_edhr_work_task.id AS CHAR) AS business_id,
CONCAT('EDHR_WORK_TASK:', mes_pro_edhr_work_task.id) AS task_key, '批记录' AS task_type, 'eDHR工作任务' AS source,
CONCAT_WS(' · ', NULLIF(REGEXP_REPLACE(CASE WHEN mes_pro_edhr_work_task.task_code IS NOT NULL AND OCTET_LENGTH(mes_pro_edhr_work_task.task_code) > 0 THEN mes_pro_edhr_work_task.task_code ELSE CONCAT('任务#', mes_pro_edhr_work_task.id) END, CONCAT('^[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+|[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+$'), ''), ''), NULLIF(REGEXP_REPLACE(mes_pro_edhr_work_task.work_order_code, CONCAT('^[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+|[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+$'), ''), ''), NULLIF(REGEXP_REPLACE(mes_pro_edhr_work_task.batch_code, CONCAT('^[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+|[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+$'), ''), ''), NULLIF(REGEXP_REPLACE(mes_pro_edhr_work_task.process_name, CONCAT('^[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+|[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+$'), ''), ''), NULLIF(REGEXP_REPLACE(CASE mes_pro_edhr_work_task.task_type WHEN 'FILL' THEN '填写' WHEN 'REVIEW' THEN '复核' WHEN 'REWORK' THEN '返工' WHEN 'ARCHIVE' THEN '归档' WHEN 'DEVIATION_RECEIVE' THEN '偏差调查' WHEN 'DEVIATION_CORRECT' THEN '偏差纠正' WHEN 'DEVIATION_SIGN' THEN '偏差签署' WHEN 'DEVIATION_APPROVE' THEN '偏差质量审核' WHEN 'DEVIATION_CLOSE' THEN '偏差关闭' WHEN 'RECORD_CHANGE_APPROVE' THEN '记录变更审批' WHEN 'DOSSIER_COMPLETE' THEN '资料补齐' WHEN 'PQC_RELEASE_CORRECTION' THEN '生产放行补正' ELSE mes_pro_edhr_work_task.task_type END, CONCAT('^[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+|[', CONVERT(UNHEX('090A0B0C0D20C2A0E19A80E28080E28081E28082E28083E28084E28085E28086E28087E28088E28089E2808AE280A8E280A9E280AFE2819FE38080EFBBBF') USING utf8mb4), ']+$'), ''), '')) AS detail, CASE WHEN EXISTS (SELECT 1 FROM mes_pro_edhr_batch_execution frozen WHERE frozen.id=mes_pro_edhr_work_task.batch_execution_id AND frozen.tenant_id=mes_pro_edhr_work_task.tenant_id AND frozen.deleted=0 AND frozen.status=15) AND mes_pro_edhr_work_task.task_type IN ('FILL','REVIEW','APPROVE','REWORK','ARCHIVE','CLOSE') THEN '批次冻结，暂不可处理' ELSE CASE mes_pro_edhr_work_task.status WHEN 'TODO' THEN '待处理' WHEN 'OVERDUE' THEN '已逾期' END END AS status_label, mes_pro_edhr_work_task.create_time AS created_at, COALESCE(mes_pro_edhr_work_task.due_time,mes_pro_edhr_work_task.overdue_at) AS due_at, mes_pro_edhr_work_task.task_type AS domain_task_type, mes_pro_edhr_work_task.action_url, CAST(mes_pro_edhr_work_task.batch_execution_id AS CHAR) AS batch_execution_id, CAST(mes_pro_edhr_work_task.batch_task_id AS CHAR) AS batch_task_id, CAST(mes_pro_edhr_work_task.execution_id AS CHAR) AS execution_id, mes_pro_edhr_work_task.business_scope_type, CAST(mes_pro_edhr_work_task.business_scope_id AS CHAR) AS business_scope_id, mes_pro_edhr_work_task.assignee_user_id AS owner_user_id, mes_pro_edhr_work_task.candidate_user_snapshot AS candidate_user_snapshot
FROM mes_pro_edhr_work_task
WHERE mes_pro_edhr_work_task.tenant_id = #{q.tenantId} AND mes_pro_edhr_work_task.deleted = 0 AND mes_pro_edhr_work_task.status IN ('TODO','OVERDUE')




AND ${correctionSql}

AND ${dossierSql}
 AND ${batchSql}
